import threading
from typing import Any, Optional

class Node:
    def __init__(self, value: Any, next_node: Optional['Node'] = None):
        self.value = value
        self.next = next_node

class LockFreeTreiberStack:
    def __init__(self):
        self._head: Optional[Node] = None
        self._lock = threading.Lock()  # Simulates hardware atomic CAS operation

    def _compare_and_swap_head(self, expected: Optional[Node], new_node: Optional[Node]) -> bool:
        with self._lock:
            if self._head is expected:
                self._head = new_node
                return True
            return False

    def push(self, val: Any) -> None:
        new_node = Node(val)
        while True:
            current_head = self._head
            new_node.next = current_head
            if self._compare_and_swap_head(current_head, new_node):
                return

    def pop(self) -> Optional[Any]:
        while True:
            current_head = self._head
            if current_head is None:
                return None
            next_node = current_head.next
            if self._compare_and_swap_head(current_head, next_node):
                return current_head.value
