@dataclass
class LogEntry:
    term: int
    index: int
    command: str

class RaftClusterValidator:
    def __init__(self, node_count: int):
        self.n = node_count
        self.majority = (node_count // 2) + 1
        self.node_logs: Dict[int, List[LogEntry]] = {i: [] for i in range(node_count)}
        self.commit_index = 0

    def append_leader_entry(self, leader_id: int, term: int, command: str) -> LogEntry:
        idx = len(self.node_logs[leader_id]) + 1
        entry = LogEntry(term=term, index=idx, command=command)
        self.node_logs[leader_id].append(entry)
        return entry

    def replicate_to_follower(self, follower_id: int, entry: LogEntry, prev_term: int, prev_idx: int) -> bool:
        f_log = self.node_logs[follower_id]
        # Log matching property check
        if prev_idx > 0:
            if len(f_log) < prev_idx or f_log[prev_idx - 1].term != prev_term:
                return False  # Inconsistency detected
        # Overwrite conflicting entries and append
        del f_log[prev_idx:]
        f_log.append(entry)
        return True

    def check_majority_committed(self, entry_index: int, entry_term: int) -> bool:
        replicated_count = 0
        for f_id, log in self.node_logs.items():
            if len(log) >= entry_index and log[entry_index - 1].term == entry_term:
                replicated_count += 1
        return replicated_count >= self.majority
