import heapq
from typing import Dict, List, Tuple, Optional

def dijkstra(graph: Dict[int, List[Tuple[int, float]]], start: int, target: int) -> Tuple[float, List[int]]:
    distances = {node: float('inf') for node in graph}
    predecessors = {node: None for node in graph}
    distances[start] = 0.0
    pq = [(0.0, start)]  # (distance, node)

    while pq:
        curr_dist, u = heapq.heappop(pq)
        if curr_dist > distances[u]:
            continue  # Outdated entry in heap
        if u == target:
            break

        for v, weight in graph.get(u, []):
            if weight < 0:
                raise ValueError('Negative edge weights not permitted in Dijkstra')
            new_dist = curr_dist + weight
            if new_dist < distances.get(v, float('inf')):
                distances[v] = new_dist
                predecessors[v] = u
                heapq.heappush(pq, (new_dist, v))

    if distances[target] == float('inf'):
        return float('inf'), []

    # Reconstruct path
    path = []
    curr = target
    while curr is not None:
        path.append(curr)
        curr = predecessors[curr]
    return distances[target], path[::-1]
```
Complexity: O((V + E) log V) time, O(V) space.

