from typing import List

def tsp_held_karp(dist_matrix: List[List[float]]) -> float:
    n = len(dist_matrix)
    memo = {}
    ALL_VISITED = (1 << n) - 1

    def get_min_cost(mask: int, u: int) -> float:
        if mask == ALL_VISITED:
            return dist_matrix[u][0]  # Return to origin city 0
        if (mask, u) in memo:
            return memo[(mask, u)]

        min_cost = float('inf')
        for v in range(n):
            if not (mask & (1 << v)):
                cost = dist_matrix[u][v] + get_min_cost(mask | (1 << v), v)
                if cost < min_cost:
                    min_cost = cost

        memo[(mask, u)] = min_cost
        return min_cost

    return get_min_cost(1, 0)  # Start at city 0 with mask 000...001
```
Complexity: O(N² 2^N) time and O(N 2^N) space.
